FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 066: isocline splits and offsets on B-spline faces, sheet and curve extensions, sweeps along chains with splines, ruled surfaces off B-spline faces. Generated by tools/fixtures/gen-batch-066.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v) returns array
{
    return [roundToPrecision(v[0] / millimeter, 6), roundToPrecision(v[1] / millimeter, 6), roundToPrecision(v[2] / millimeter, 6)];
}

// Each face of a body: its area, its surface's type, and for a B-spline its degrees, knots and poles. (Batch 055's
// first build: taking a B-spline's knots with mapArray failed in Onshape with "Execution error"; indexed loops,
// each part caught on its own.)
function faceProbe(context is Context, body is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qOwnedByBody(body, EntityType.FACE)))
    {
        var entry = { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6) };
        try
        {
            const s = evSurfaceDefinition(context, { "face" : face });
            entry["type"] = s.surfaceType;
            if (s is BSplineSurface)
                entry.bspline = bsplineProbe(s);
        }
        catch (error)
        {
            entry["type"] = "failed";
        }
        out = append(out, entry);
    }
    return out;
}

// Knot arrays and control point matrices are typed: indexed, as std does, rather than iterated.
function knotsProbe(knots) returns array
{
    var out = [];
    for (var i = 0; i < size(knots); i += 1)
        out = append(out, roundToPrecision(knots[i], 9));
    return out;
}

function bsplineProbe(s) returns map
{
    var b = { "uDegree" : s.uDegree, "vDegree" : s.vDegree, "rational" : s.isRational };
    try
    {
        b.uKnots = knotsProbe(s.uKnots);
        b.vKnots = knotsProbe(s.vKnots);
    }
    catch (error)
    {
        b.knots = "failed";
    }
    try
    {
        const matrix = s.controlPoints;
        var rows = [];
        for (var i = 0; i < size(matrix); i += 1)
        {
            var points = [];
            for (var j = 0; j < size(matrix[i]); j += 1)
                points = append(points, round6(matrix[i][j]));
            rows = append(rows, points);
        }
        b.poles = rows;
    }
    catch (error)
    {
        b.poles = "failed";
    }
    return b;
}

// Nine points along each edge of a body, evenly spaced in its own parameter.
function edgeProbe(context is Context, body is Query) returns array
{
    var out = [];
    for (var edge in evaluateQuery(context, qOwnedByBody(body, EntityType.EDGE)))
    {
        const lines = evEdgeTangentLines(context, { "edge" : edge, "parameters" : [0, 0.125, 0.25, 0.375, 0.5, 0.625, 0.75, 0.875, 1], "arcLengthParameterization" : false });
        var points = [];
        for (var l in lines)
            points = append(points, round6(l.origin));
        out = append(out, points);
    }
    return out;
}

// Each edge of a body: its ends and its length.
function edgeEnds(context is Context, body is Query) returns array
{
    var out = [];
    for (var edge in evaluateQuery(context, qOwnedByBody(body, EntityType.EDGE)))
    {
        const lines = evEdgeTangentLines(context, { "edge" : edge, "parameters" : [0, 0.5, 1], "arcLengthParameterization" : false });
        out = append(out, { "start" : round6(lines[0].origin), "middle" : round6(lines[1].origin), "end" : round6(lines[2].origin),
                            "length" : roundToPrecision(evLength(context, { "entities" : edge }) / millimeter, 6) });
    }
    return out;
}

// A coordinate system's numbers, in mm, for comparing.
function frameProbe(cs) returns map
{
    return { "origin" : round6(cs.origin), "x" : [roundToPrecision(cs.xAxis[0], 6), roundToPrecision(cs.xAxis[1], 6), roundToPrecision(cs.xAxis[2], 6)],
             "z" : [roundToPrecision(cs.zAxis[0], 6), roundToPrecision(cs.zAxis[1], 6), roundToPrecision(cs.zAxis[2], 6)] };
}

// The coordinate systems of a body's cylindrical faces.
function cylinderFrames(context is Context, body is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qGeometry(qOwnedByBody(body, EntityType.FACE), GeometryType.CYLINDER)))
        out = append(out, frameProbe(evSurfaceDefinition(context, { "face" : face }).coordSystem));
    return out;
}

// A sheet metal plate 40 x 30, 2 mm thick, with a 10 mm flange up from its y = 30 edge.
function smBracket(context is Context, id is Id)
{
    const sketch = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * meter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(sketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(sketch);
    sheetMetalStart(context, id + "sm1", { "process" : SMProcessType.THICKEN, "regions" : qSketchRegion(id + "s1"),
                                   "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter,
                                   "flipDirectionUp" : false, "tangentPropagation" : false, "bends" : qNothing() });
    const part = qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID);
    sheetMetalFlange(context, id + "flange1", {
            "edges" : qClosestTo(qOwnedByBody(part, EntityType.EDGE), vector(20, 30, 2) * millimeter),
            "flangeAlignment" : SMFlangeAlignment.INNER, "limitType" : SMFlangeBoundingType.BLIND, "distance" : 10 * millimeter,
            "angleControlType" : SMFlangeAngleControlType.BEND_ANGLE, "oppositeDirection" : false, "bendAngle" : 90 * degree,
            "autoMiter" : true, "useDefaultRadius" : true });
}

// A sheet metal plate 40 x 30, 2 mm thick, with 10 mm flanges up from both its y = 0 and y = 30 edges (a channel).
function smChannel(context is Context, id is Id)
{
    const sketch = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * meter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(sketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(sketch);
    sheetMetalStart(context, id + "sm1", { "process" : SMProcessType.THICKEN, "regions" : qSketchRegion(id + "s1"),
                                   "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter,
                                   "flipDirectionUp" : false, "tangentPropagation" : false, "bends" : qNothing() });
    const part = qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID);
    sheetMetalFlange(context, id + "flange1", {
            "edges" : qUnion([qClosestTo(qOwnedByBody(part, EntityType.EDGE), vector(20, 30, 2) * millimeter),
                              qClosestTo(qOwnedByBody(part, EntityType.EDGE), vector(20, 0, 2) * millimeter)]),
            "flangeAlignment" : SMFlangeAlignment.INNER, "limitType" : SMFlangeBoundingType.BLIND, "distance" : 10 * millimeter,
            "angleControlType" : SMFlangeAngleControlType.BEND_ANGLE, "oppositeDirection" : false, "bendAngle" : 90 * degree,
            "autoMiter" : true, "useDefaultRadius" : true });
}

// A sheet metal plate 40 x 30, 2 mm thick, 1 mm bends, with a flange of "distance" from the edge nearest "edgePoint",
// bent "angle" (up, or down if "down").
function smFlanged(context is Context, id is Id, edgePoint is Vector, distance is ValueWithUnits, angle is ValueWithUnits, down is boolean)
{
    const sketch = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * meter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(sketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(sketch);
    sheetMetalStart(context, id + "sm1", { "process" : SMProcessType.THICKEN, "regions" : qSketchRegion(id + "s1"),
                                   "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter,
                                   "flipDirectionUp" : false, "tangentPropagation" : false, "bends" : qNothing() });
    const part = qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID);
    sheetMetalFlange(context, id + "flange1", {
            "edges" : qClosestTo(qOwnedByBody(part, EntityType.EDGE), edgePoint),
            "flangeAlignment" : SMFlangeAlignment.INNER, "limitType" : SMFlangeBoundingType.BLIND, "distance" : distance,
            "angleControlType" : SMFlangeAngleControlType.BEND_ANGLE, "oppositeDirection" : down, "bendAngle" : angle,
            "autoMiter" : true, "useDefaultRadius" : true });
}

// isocline: the sides of batch 065 c003's loft split at 30° to z
export function c001(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "r", { "firstCorner" : vector(-10, -10) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s2, "r", { "firstCorner" : vector(-5, -5) * millimeter, "secondCorner" : vector(5, 5) * millimeter });
    skSolve(s2);
    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "s1") }, { "sheetProfileEntities" : qSketchRegion(id + "s2") }], "startCondition" : LoftEndDerivativeType.TANGENT_TO_PROFILE, "startMagnitude" : 1 });
    isocline(context, id + "iso1", { "faces" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.OTHER_SURFACE), "direction" : qContainsPoint(qCreatedBy(makeId("Top"), EntityType.FACE), vector(0, 0, 0) * meter), "oppositeDirection" : false, "angle" : 30 * degree, "split" : true });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID)) };
}

// extend-surface: batch 065 c004's sheet extended 3 mm past its straight side at x = 30
export function c002(context is Context, id is Id)
{
    const a1 = newSketchOnPlane(context, id + "a1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skArc(a1, "arc1", { "start" : vector(0, 0) * millimeter, "mid" : vector(15, 6) * millimeter, "end" : vector(30, 0) * millimeter });
    skSolve(a1);
    const a2 = newSketchOnPlane(context, id + "a2", { "sketchPlane" : plane(vector(0, 20, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skArc(a2, "arc1", { "start" : vector(0, 0) * millimeter, "mid" : vector(15, 10) * millimeter, "end" : vector(30, 0) * millimeter });
    skSolve(a2);
    loft(context, id + "sheet", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceOperationType" : NewSurfaceOperationType.NEW, "wireProfilesArray" : [{ "wireProfileEntities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "a1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]) }, { "wireProfileEntities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "a2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]) }] });
    extendSurface(context, id + "extend1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "sheet", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(30, 10, 0) * millimeter), "endCondition" : ExtendBoundingType.BLIND, "extendDistance" : 3 * millimeter, "oppositeDirection" : false, "maintainCurvature" : false, "tangentPropagation" : false });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "sheet", EntityType.BODY), BodyType.SHEET)), "edges" : edgeProbe(context, qBodyType(qCreatedBy(id + "sheet", EntityType.BODY), BodyType.SHEET)) };
}

// trim-curve: a quarter circle of radius 10 extended at its end up to a circle of radius 5 about (-5, 8)
export function c003(context is Context, id is Id)
{
    const c = newSketchOnPlane(context, id + "c", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(c, "a1", { "start" : vector(10, 0) * millimeter, "mid" : vector(7.071068, 7.071068) * millimeter, "end" : vector(0, 10) * millimeter });
    skSolve(c);
    compositeCurve(context, id + "curve1", { "edges" : qOwnedByBody(qBodyType(qCreatedBy(id + "c", EntityType.BODY), BodyType.WIRE), EntityType.EDGE) });
    const limit = newSketchOnPlane(context, id + "limit", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(limit, "c1", { "center" : vector(-5, 8) * millimeter, "radius" : 5 * millimeter });
    skSolve(limit);
    trimCurve(context, id + "trim1", { "moveBoundaryType" : MoveCurveBoundaryType.EXTEND, "wires" : qBodyType(qCreatedBy(id + "curve1", EntityType.BODY), BodyType.WIRE), "endCondition" : CurveExtensionEndCondition.UP_TO_ENTITY, "extendTo" : qCreatedBy(id + "limit", EntityType.EDGE), "extensionShape" : CurveExtensionShape.TANGENT, "helpPoint" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "curve1", EntityType.BODY), BodyType.WIRE), EntityType.VERTEX), vector(0, 10, 0) * millimeter), "flipHeuristics" : false });
    return { "edges" : edgeEnds(context, qBodyType(qCreatedBy(id + "curve1", EntityType.BODY), BodyType.WIRE)) };
}

