    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s2, "r", { "firstCorner" : vector(-5, -5) * millimeter, "secondCorner" : vector(5, 5) * millimeter });
    skSolve(s2);
    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "s1") }, { "sheetProfileEntities" : qSketchRegion(id + "s2") }], "startCondition" : LoftEndDerivativeType.TANGENT_TO_PROFILE, "startMagnitude" : 1 });
    offsetCurveOnFace(context, id + "offset1", { "edges" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(-10, 0, 0) * millimeter), "distance" : 4 * millimeter, "offsetType" : OffsetCurveType.GEODESIC, "oppositeDirection" : false, "gapFill" : GapFill.LINEAR, "scope" : OffsetCurveScope.OFFSET, "targets" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(-9.279898, 0, 0.648481) * millimeter) });
